                and (dce2.start_time::date AT TIME ZONE 'UTC' AT TIME ZONE 'US/Mountain')::date = permit_pack_revision_submittal_date::date
                and dce2.deleted is false
            where
                permit_pack_revision_submittal_date is not null
              and originator_id = 1
